import type { ContentPack } from '../types';
import { lesson, M, Nq, TF } from '../lib';

const P: ContentPack = {
  '3E-BG-1': lesson(['Grandes aportaciones a la salud y la biología humana: Hipócrates (observar al enfermo), Jenner (primera vacuna), Pasteur (microbios), Fleming (penicilina), Ramón y Cajal (neuronas), Margarita Salas (ADN), Katalin Karikó (vacunas de ARNm).|Grans aportacions a la salut i la biologia humana: Hipòcrates (observar el malalt), Jenner (primera vacuna), Pasteur (microbis), Fleming (penicil·lina), Ramón y Cajal (neurones), Margarita Salas (ADN), Katalin Karikó (vacunes d’ARNm).|Major contributions to health and human biology: Hippocrates (observing the patient), Jenner (first vaccine), Pasteur (germs), Fleming (penicillin), Ramón y Cajal (neurons), Margarita Salas (DNA), Katalin Karikó (mRNA vaccines).'],
    '¿Quién desarrolló la primera vacuna?|Qui va desenvolupar la primera vacuna?|Who developed the first vaccine?', ['Contra la viruela, en 1796.|Contra la verola, el 1796.|Against smallpox, in 1796.', 'Edward Jenner.|Edward Jenner.|Edward Jenner.'], [
      M('Louis Pasteur demostró que muchas enfermedades las causan…|Louis Pasteur va demostrar que moltes malalties les causen…|Louis Pasteur showed that many diseases are caused by…', 'microorganismos|microorganismes|microorganisms', ['los astros|els astres|the stars', 'el frío|el fred|the cold'], 'Teoría germinal.|Teoria germinal.|Germ theory.'),
      M('Alexander Fleming descubrió…|Alexander Fleming va descobrir…|Alexander Fleming discovered…', 'la penicilina|la penicil·lina|penicillin', ['la insulina|la insulina|insulin', 'el ADN|l’ADN|DNA'], 'El primer antibiótico.|El primer antibiòtic.|The first antibiotic.'),
      M('Katalin Karikó y Drew Weissman ganaron el Nobel en 2023 por…|Katalin Karikó i Drew Weissman van guanyar el Nobel el 2023 per…|Katalin Karikó and Drew Weissman won the 2023 Nobel Prize for…', 'las vacunas de ARN mensajero|les vacunes d’ARN missatger|messenger RNA vaccines', ['el telescopio|el telescopi|the telescope', 'los rayos X|els raigs X|X-rays'], 'Clave contra la COVID-19.|Clau contra la COVID-19.|Key against COVID-19.'),
      M('Ramón y Cajal demostró que el sistema nervioso está formado por…|Ramón y Cajal va demostrar que el sistema nerviós està format per…|Ramón y Cajal showed the nervous system is made of…', 'células independientes: las neuronas|cèl·lules independents: les neurones|separate cells: neurons', ['una red continua|una xarxa contínua|one continuous network', 'huesos|ossos|bones'], 'Nobel en 1906.|Nobel el 1906.|Nobel Prize 1906.'),
      TF('Lavarse las manos es una medida sanitaria que salva muchas vidas.|Llavar-se les mans és una mesura sanitària que salva moltes vides.|Handwashing is a health measure that saves many lives.', true, 'Semmelweis lo demostró en el siglo XIX.|Semmelweis ho va demostrar en el segle XIX.|Semmelweis showed this in the 19th century.'),
      M('Hipócrates es conocido como el padre de…|Hipòcrates és conegut com el pare de…|Hippocrates is known as the father of…', 'la medicina|la medicina|medicine', ['la química|la química|chemistry', 'la geología|la geologia|geology'], 'Antigua Grecia.|Antiga Grècia.|Ancient Greece.'),
    ]),
  '3E-BG-2': lesson(['Un proyecto de investigación en biología: plantear una pregunta, buscar información previa, formular una hipótesis, diseñar el experimento con grupo de control, recoger y analizar datos y comunicar conclusiones. En estudios con personas, se respeta su consentimiento y su privacidad.|Un projecte d’investigació en biologia: plantejar una pregunta, buscar informació prèvia, formular una hipòtesi, dissenyar l’experiment amb grup de control, recollir i analitzar dades i comunicar conclusions. En estudis amb persones, es respecta el seu consentiment i la seua privacitat.|A biology research project: ask a question, find background information, form a hypothesis, design an experiment with a control group, collect and analyse data and share conclusions. Studies with people must respect their consent and privacy.'],
    '¿Influye el ejercicio en el pulso?|Influïx l’exercici en el pols?|Does exercise affect pulse rate?', ['Mido el pulso en reposo y tras correr 2 min.|Mesure el pols en repòs i després de córrer 2 min.|Measure the pulse at rest and after running 2 min.', 'Comparo con varias personas y calculo la media.|Compare amb diverses persones i calcule la mitjana.|Compare several people and find the mean.'], [
      M('En un experimento con plantas, el grupo de control…|En un experiment amb plantes, el grup de control…|In a plant experiment, the control group…', 'no recibe el tratamiento que se estudia|no rep el tractament que s’estudia|does not get the treatment being tested', ['recibe el doble de agua|rep el doble d’aigua|gets twice the water', 'se tira|es llança|is thrown away'], 'Sirve de referencia.|Servix de referència.|It is the baseline.'),
      TF('Los datos personales de un estudio deben protegerse.|Les dades personals d’un estudi s’han de protegir.|Personal data in a study must be protected.', true, 'Por ejemplo, anonimizándolos.|Per exemple, anonimitzant-les.|For example, by anonymising them.'),
      M('¿Por qué conviene usar muchos individuos en un estudio?|Per què convé usar molts individus en un estudi?|Why use many individuals in a study?', 'para que los resultados sean más fiables|perquè els resultats siguen més fiables|so the results are more reliable', ['para que dure más|perquè dure més|so it takes longer', 'para gastar más|per a gastar més|to spend more'], 'Un caso aislado puede ser excepcional.|Un cas aïllat pot ser excepcional.|One case may be unusual.'),
      M('¿Qué gráfico es mejor para ver cómo cambia el pulso con el tiempo?|Quin gràfic és millor per a veure com canvia el pols amb el temps?|Which graph best shows how pulse changes over time?', 'un gráfico de líneas|un gràfic de línies|a line graph', ['un gráfico de sectores|un gràfic de sectors|a pie chart', 'un mapa|un mapa|a map'], 'Muestra la evolución.|Mostra l’evolució.|It shows change over time.'),
      TF('Una conclusión puede decir «nuestros datos no apoyan la hipótesis».|Una conclusió pot dir «les nostres dades no donen suport a la hipòtesi».|A conclusion can say "our data does not support the hypothesis".', true, 'También es un resultado.|També és un resultat.|That is still a result.'),
      M('Antes de diseñar el experimento conviene…|Abans de dissenyar l’experiment convé…|Before designing the experiment you should…', 'buscar qué se sabe ya del tema|buscar què se sap ja del tema|find out what is already known', ['escribir las conclusiones|escriure les conclusions|write the conclusions', 'publicar los resultados|publicar els resultats|publish the results'], 'Información previa.|Informació prèvia.|Background research.'),
    ]),
  '3E-BG-3': lesson(['En el laboratorio de biología se usan microscopio, lupa, portaobjetos y cubreobjetos, colorantes (azul de metileno), bisturí y pinzas. Normas: bata, guantes cuando toca, no comer, desechar los residuos biológicos en su contenedor.|Al laboratori de biologia s’usen microscopi, lupa, portaobjectes i cobreobjectes, colorants (blau de metilé), bisturí i pinces. Normes: bata, guants quan toca, no menjar, rebutjar els residus biològics en el seu contenidor.|In the biology lab we use a microscope, hand lens, slides and cover slips, stains (methylene blue), scalpel and tweezers. Rules: lab coat, gloves when needed, no eating, put biological waste in its own bin.'],
    '¿Cómo se ven las células de la mucosa de la boca?|Com es veuen les cèl·lules de la mucosa de la boca?|How do you look at cheek cells?', ['Raspo suavemente con un palillo y extiendo en un portaobjetos.|Rasque suaument amb un escuradents i estenc en un portaobjectes.|Gently scrape with a cotton bud and smear on a slide.', 'Tiño con azul de metileno y pongo el cubreobjetos.|Tinc amb blau de metilé i pose el cobreobjectes.|Stain with methylene blue and add a cover slip.'], [
      M('El azul de metileno sirve para…|El blau de metilé servix per a…|Methylene blue is used to…', 'teñir y ver mejor el núcleo|tenyir i veure millor el nucli|stain cells so the nucleus shows up', ['matar bacterias|matar bacteris|kill bacteria', 'calentar la muestra|escalfar la mostra|heat the sample'], 'Colorante.|Colorant.|A stain.'),
      M('Al enfocar al microscopio se empieza por el objetivo de…|En enfocar al microscopi es comença per l’objectiu de…|When focusing a microscope, start with the objective that has…', 'menor aumento|menor augment|the lowest magnification', ['mayor aumento|major augment|the highest magnification', 'cualquiera|qualsevol|any one'], 'Así se localiza la muestra.|Així es localitza la mostra.|That helps you find the sample.'),
      TF('El cubreobjetos se coloca para proteger la muestra y el objetivo.|El cobreobjectes es col·loca per a protegir la mostra i l’objectiu.|The cover slip protects the sample and the lens.', true, 'Y aplana la preparación.|I aplana la preparació.|And flattens the sample.'),
      Nq('Ocular ×10 y objetivo ×100. ¿Aumento total?|Ocular ×10 i objectiu ×100. Augment total?|Eyepiece ×10, objective ×100. Total magnification?', 1000, [110, 100, 10000], 'Multiplica.|Multiplica.|Multiply.'),
      M('Los guantes usados con muestras biológicas se tiran…|Els guants usats amb mostres biològiques es tiren…|Gloves used with biological samples go…', 'al contenedor de residuos biológicos|al contenidor de residus biològics|in the biological waste bin', ['al de papel|al de paper|in the paper bin', 'al suelo|a terra|on the floor'], 'Pueden llevar microorganismos.|Poden portar microorganismes.|They may carry microbes.'),
      M('Para diseccionar se usa…|Per a dissecar s’usa…|For dissection you use…', 'bisturí y pinzas|bisturí i pinces|a scalpel and tweezers', ['probeta|proveta|a measuring cylinder', 'termómetro|termòmetre|a thermometer'], 'Con mucho cuidado.|Amb molta cura.|With great care.'),
    ]),
  '3E-BG-4': lesson(['Para buscar información sobre salud: fuentes fiables como el Ministerio de Sanidad, la OMS o sociedades médicas; desconfía de remedios milagro, de quien vende algo y de lo que no cita estudios. Comunicar ciencia es explicar con claridad, con datos y citando fuentes.|Per a buscar informació sobre salut: fonts fiables com el Ministeri de Sanitat, l’OMS o societats mèdiques; desconfia de remeis miraculosos, de qui ven alguna cosa i del que no cita estudis. Comunicar ciència és explicar amb claredat, amb dades i citant fonts.|For health information use reliable sources such as the Ministry of Health, the WHO or medical societies; be wary of miracle cures, people selling something, and claims without studies. Communicating science means explaining clearly, with data and sources.'],
    'Una web dice que un batido cura la diabetes. ¿Fiable?|Una web diu que un batut cura la diabetis. Fiable?|A website says a shake cures diabetes. Reliable?', ['Promete una cura milagro y vende el producto.|Promet una cura miraculosa i ven el producte.|It promises a miracle cure and sells the product.', 'No es fiable; consulta fuentes médicas oficiales.|No és fiable; consulta fonts mèdiques oficials.|Not reliable; check official medical sources.'], [
      M('¿Qué fuente es más fiable sobre vacunas?|Quina font és més fiable sobre vacunes?|Which source is most reliable about vaccines?', 'la Organización Mundial de la Salud|l’Organització Mundial de la Salut|the World Health Organization', ['un foro anónimo|un fòrum anònim|an anonymous forum', 'un vídeo sin autor|un vídeo sense autor|a video with no author'], 'Organismo oficial.|Organisme oficial.|An official body.'),
      TF('Si algo lo dice un famoso, está demostrado científicamente.|Si alguna cosa la diu un famós, està demostrada científicament.|If a celebrity says it, it is scientifically proven.', false, 'La fama no es una prueba.|La fama no és una prova.|Fame is not evidence.'),
      M('Una señal de bulo sanitario es…|Un senyal de bulo sanitari és…|A sign of a health hoax is…', 'prometer resultados milagrosos|prometre resultats miraculosos|promising miracle results', ['citar estudios revisados|citar estudis revisats|citing peer-reviewed studies', 'tener autor y fecha|tindre autor i data|having an author and date'], 'Demasiado bueno para ser verdad.|Massa bo per a ser veritat.|Too good to be true.'),
      M('Al hacer un póster científico, lo esencial es…|En fer un pòster científic, l’essencial és…|When making a science poster, the key is…', 'título claro, datos, gráficos y fuentes|títol clar, dades, gràfics i fonts|a clear title, data, graphs and sources', ['mucho texto pequeño|molt de text xicotet|lots of small text', 'solo dibujos|només dibuixos|only drawings'], 'Que se entienda rápido.|Que s’entenga ràpid.|Easy to grasp quickly.'),
      TF('Ante dudas de salud, lo correcto es consultar a profesionales sanitarios.|Davant de dubtes de salut, el correcte és consultar professionals sanitaris.|For health questions, ask health professionals.', true, 'Internet no sustituye a una consulta.|Internet no substituïx una consulta.|The internet does not replace a doctor.'),
      M('Para comprobar una noticia de salud se debe…|Per a comprovar una notícia de salut s’ha de…|To check a health story you should…', 'buscar la fuente original y contrastarla|buscar la font original i contrastar-la|find the original source and cross-check it', ['compartirla primero|compartir-la primer|share it first', 'fiarse del titular|fiar-se del titular|trust the headline'], 'Contrastar.|Contrastar.|Cross-check.'),
    ]),
  '3E-BG-5': lesson(['El cuerpo humano se organiza en niveles: células → tejidos (epitelial, conectivo, muscular, nervioso) → órganos → aparatos y sistemas → organismo. Todos trabajan coordinados.|El cos humà s’organitza en nivells: cèl·lules → teixits (epitelial, connectiu, muscular, nerviós) → òrgans → aparells i sistemes → organisme. Tots treballen coordinats.|The human body is organised in levels: cells → tissues (epithelial, connective, muscle, nervous) → organs → organ systems → organism. They all work together.'],
    '¿Qué tejido recubre la piel y los órganos?|Quin teixit recobrix la pell i els òrgans?|Which tissue covers the skin and organs?', ['Forma capas protectoras.|Forma capes protectores.|It forms protective layers.', 'El tejido epitelial.|El teixit epitelial.|Epithelial tissue.'], [
      M('El tejido que permite el movimiento es el…|El teixit que permet el moviment és el…|The tissue that allows movement is…', 'muscular|muscular|muscle tissue', ['epitelial|epitelial|epithelial tissue', 'adiposo|adipós|fat tissue'], 'Se contrae.|Es contrau.|It contracts.'),
      M('Los huesos y la sangre son tejidos…|Els ossos i la sang són teixits…|Bone and blood are…', 'conectivos|connectius|connective tissues', ['nerviosos|nerviosos|nervous tissues', 'epiteliales|epitelials|epithelial tissues'], 'Unen, sostienen o transportan.|Unixen, sostenen o transporten.|They join, support or transport.'),
      M('El estómago es…|L’estómac és…|The stomach is…', 'un órgano|un òrgan|an organ', ['un tejido|un teixit|a tissue', 'una célula|una cèl·lula|a cell'], 'Formado por varios tejidos.|Format per diversos teixits.|Made of several tissues.'),
      TF('Las neuronas forman el tejido nervioso.|Les neurones formen el teixit nerviós.|Neurons make up nervous tissue.', true, 'Transmiten impulsos.|Transmeten impulsos.|They carry impulses.'),
      M('El aparato circulatorio incluye…|L’aparell circulatori inclou…|The circulatory system includes…', 'corazón, vasos sanguíneos y sangre|cor, vasos sanguinis i sang|the heart, blood vessels and blood', ['pulmones y tráquea|pulmons i tràquea|lungs and windpipe', 'riñones y vejiga|ronyons i bufeta|kidneys and bladder'], 'Transporta sustancias.|Transporta substàncies.|It transports substances.'),
      M('Ordena de menor a mayor:|Ordena de menor a major:|Order from smallest to largest:', 'célula, tejido, órgano, aparato|cèl·lula, teixit, òrgan, aparell|cell, tissue, organ, system', ['tejido, célula, aparato, órgano|teixit, cèl·lula, aparell, òrgan|tissue, cell, system, organ', 'órgano, tejido, célula, aparato|òrgan, teixit, cèl·lula, aparell|organ, tissue, cell, system'], 'De lo simple a lo complejo.|Del simple al complex.|Simple to complex.'),
    ]),
  '3E-BG-6': lesson(['Nuestro cuerpo tiene unos 30 billones de células de más de 200 tipos, todas eucariotas animales: neuronas (largas, transmiten impulsos), glóbulos rojos (sin núcleo, llevan oxígeno), células musculares (alargadas), gametos (óvulo y espermatozoide)…|El nostre cos té uns 30 bilions de cèl·lules de més de 200 tipus, totes eucariotes animals: neurones (llargues, transmeten impulsos), glòbuls rojos (sense nucli, porten oxigen), cèl·lules musculars (allargades), gàmetes (òvul i espermatozou)…|Our body has about 30 trillion cells of over 200 types, all animal eukaryotic cells: neurons (long, carry impulses), red blood cells (no nucleus, carry oxygen), muscle cells (elongated), gametes (egg and sperm)…'],
    '¿Por qué los glóbulos rojos no tienen núcleo?|Per què els glòbuls rojos no tenen nucli?|Why do red blood cells have no nucleus?', ['Así caben más moléculas de hemoglobina.|Així hi caben més molècules d’hemoglobina.|So more haemoglobin fits in.', 'Transportan más oxígeno.|Transporten més oxigen.|They carry more oxygen.'], [
      M('¿Qué célula transmite impulsos nerviosos?|Quina cèl·lula transmet impulsos nerviosos?|Which cell carries nerve impulses?', 'la neurona|la neurona|the neuron', ['el glóbulo rojo|el glòbul roig|the red blood cell', 'el óvulo|l’òvul|the egg cell'], 'Tiene dendritas y axón.|Té dendrites i axó.|It has dendrites and an axon.'),
      M('La célula más grande del cuerpo humano es…|La cèl·lula més gran del cos humà és…|The largest human cell is…', 'el óvulo|l’òvul|the egg cell', ['el espermatozoide|l’espermatozou|the sperm cell', 'la plaqueta|la plaqueta|the platelet'], 'Se ve casi a simple vista.|Es veu quasi a simple vista.|It is almost visible to the naked eye.'),
      M('Los glóbulos blancos sirven para…|Els glòbuls blancs servixen per a…|White blood cells are used to…', 'defendernos de infecciones|defendre’ns d’infeccions|defend us against infection', ['transportar oxígeno|transportar oxigen|carry oxygen', 'coagular la sangre|coagular la sang|clot blood'], 'Sistema inmunitario.|Sistema immunitari.|The immune system.'),
      TF('Todas las células humanas tienen el mismo ADN, pero usan genes distintos.|Totes les cèl·lules humanes tenen el mateix ADN, però usen gens diferents.|All human cells have the same DNA but use different genes.', true, 'Por eso se especializan.|Per això s’especialitzen.|That is how they specialise.'),
      M('El espermatozoide tiene un flagelo para…|L’espermatozou té un flagel per a…|A sperm cell has a tail (flagellum) to…', 'desplazarse|desplaçar-se|swim', ['alimentarse|alimentar-se|feed', 'hacer la fotosíntesis|fer la fotosíntesi|photosynthesise'], 'Debe llegar hasta el óvulo.|Ha d’arribar fins a l’òvul.|It must reach the egg.'),
      M('Las plaquetas intervienen en…|Les plaquetes intervenen en…|Platelets help with…', 'la coagulación de la sangre|la coagulació de la sang|blood clotting', ['la digestión|la digestió|digestion', 'la visión|la visió|vision'], 'Taponan las heridas.|Taponen les ferides.|They seal wounds.'),
    ]),
  '3E-BG-7': lesson(['Nutrientes: hidratos de carbono (energía: pan, arroz), lípidos (energía y reserva: aceite), proteínas (construir y reparar: carne, legumbres, huevos), vitaminas y minerales (regulan: fruta, verdura) y agua. La dieta mediterránea es variada, rica en frutas, verduras, legumbres y aceite de oliva.|Nutrients: hidrats de carboni (energia: pa, arròs), lípids (energia i reserva: oli), proteïnes (construir i reparar: carn, llegums, ous), vitamines i minerals (regulen: fruita, verdura) i aigua. La dieta mediterrània és variada, rica en fruites, verdures, llegums i oli d’oliva.|Nutrients: carbohydrates (energy: bread, rice), fats (energy and storage: oil), proteins (building and repair: meat, pulses, eggs), vitamins and minerals (regulation: fruit, vegetables) and water. The Mediterranean diet is varied and rich in fruit, vegetables, pulses and olive oil.'],
    '¿Qué nutriente predomina en las lentejas?|Quin nutrient predomina en les llentilles?|Which nutrient is high in lentils?', ['Las legumbres son ricas en proteínas vegetales.|Els llegums són rics en proteïnes vegetals.|Pulses are rich in plant protein.', 'Proteínas (y también hidratos y fibra).|Proteïnes (i també hidrats i fibra).|Protein (also carbohydrates and fibre).'], [
      M('La función principal de los hidratos de carbono es…|La funció principal dels hidrats de carboni és…|The main role of carbohydrates is…', 'dar energía|donar energia|to provide energy', ['formar huesos|formar ossos|to build bones', 'transportar oxígeno|transportar oxigen|to carry oxygen'], 'Pan, pasta, arroz, patata.|Pa, pasta, arròs, creïlla.|Bread, pasta, rice, potatoes.'),
      M('La vitamina C abunda en…|La vitamina C abunda en…|Vitamin C is plentiful in…', 'cítricos como la naranja|cítrics com la taronja|citrus fruit such as oranges', ['el aceite|l’oli|oil', 'el pan blanco|el pa blanc|white bread'], 'Ayuda a las defensas.|Ajuda les defenses.|It supports immunity.'),
      M('El calcio, necesario para los huesos, está sobre todo en…|El calci, necessari per als ossos, està sobretot en…|Calcium, needed for bones, is mainly in…', 'los lácteos|els lactis|dairy products', ['los refrescos|els refrescos|fizzy drinks', 'las chucherías|les llepolies|sweets'], 'Leche, yogur, queso.|Llet, iogurt, formatge.|Milk, yoghurt, cheese.'),
      TF('Una dieta equilibrada incluye alimentos de todos los grupos.|Una dieta equilibrada inclou aliments de tots els grups.|A balanced diet includes foods from every group.', true, 'Variedad y moderación.|Varietat i moderació.|Variety and moderation.'),
      M('¿Qué alimento conviene tomar solo de vez en cuando?|Quin aliment convé prendre només de tant en tant?|Which food is best eaten only occasionally?', 'bollería industrial|brioixeria industrial|packaged pastries', ['fruta|fruita|fruit', 'legumbres|llegums|pulses'], 'Mucho azúcar y grasas poco saludables.|Molt de sucre i greixos poc saludables.|Lots of sugar and unhealthy fats.'),
      M('La fibra, presente en verduras y cereales integrales, ayuda a…|La fibra, present en verdures i cereals integrals, ajuda a…|Fibre, found in vegetables and wholegrains, helps…', 'el buen funcionamiento del intestino|el bon funcionament de l’intestí|keep the gut working well', ['construir músculo|construir múscul|build muscle', 'ver de noche|veure de nit|see at night'], 'Evita el estreñimiento.|Evita el restrenyiment.|It prevents constipation.'),
    ]),
  '3E-BG-8': lesson(['La nutrición humana implica cuatro aparatos: digestivo (transforma los alimentos en nutrientes y los absorbe), respiratorio (toma O₂ y expulsa CO₂), circulatorio (transporta nutrientes, gases y desechos) y excretor (elimina desechos: riñones y orina).|La nutrició humana implica quatre aparells: digestiu (transforma els aliments en nutrients i els absorbix), respiratori (pren O₂ i expulsa CO₂), circulatori (transporta nutrients, gasos i deixalles) i excretor (elimina deixalles: ronyons i orina).|Human nutrition involves four systems: digestive (breaks food into nutrients and absorbs them), respiratory (takes in O₂ and gets rid of CO₂), circulatory (carries nutrients, gases and waste) and excretory (removes waste: kidneys and urine).'],
    '¿Dónde pasan los nutrientes a la sangre?|On passen els nutrients a la sang?|Where do nutrients pass into the blood?', ['Tras la digestión en estómago e intestino.|Després de la digestió en estómac i intestí.|After digestion in the stomach and intestine.', 'En el intestino delgado (vellosidades).|En l’intestí prim (vellositats).|In the small intestine (villi).'], [
      M('El intercambio de gases ocurre en los…|L’intercanvi de gasos ocorre en els…|Gas exchange happens in the…', 'alvéolos pulmonares|alvèols pulmonars|alveoli of the lungs', ['bronquios|bronquis|bronchi', 'riñones|ronyons|kidneys'], 'Paredes muy finas con capilares.|Parets molt fines amb capil·lars.|Very thin walls with capillaries.'),
      M('Los riñones filtran la sangre y producen…|Els ronyons filtren la sang i produïxen…|The kidneys filter blood and make…', 'orina|orina|urine', ['bilis|bilis|bile', 'saliva|saliva|saliva'], 'Elimina urea y exceso de agua.|Elimina urea i excés d’aigua.|It removes urea and extra water.'),
      Nq('¿Cuántas cavidades tiene el corazón humano?|Quantes cavitats té el cor humà?|How many chambers does the human heart have?', 4, [2, 3, 6], 'Dos aurículas y dos ventrículos.|Dues aurícules i dos ventricles.|Two atria and two ventricles.'),
      M('Las arterias llevan la sangre…|Les artèries porten la sang…|Arteries carry blood…', 'desde el corazón hacia el cuerpo|des del cor cap al cos|away from the heart', ['hacia el corazón|cap al cor|towards the heart', 'solo a los pulmones|només als pulmons|only to the lungs'], 'Las venas la devuelven.|Les venes la tornen.|Veins bring it back.'),
      M('La saliva empieza la digestión de…|La saliva comença la digestió de…|Saliva starts digesting…', 'el almidón|el midó|starch', ['las proteínas|les proteïnes|proteins', 'las grasas|els greixos|fats'], 'Contiene amilasa.|Conté amilasa.|It contains amylase.'),
      TF('El hígado produce la bilis, que ayuda a digerir las grasas.|El fetge produïx la bilis, que ajuda a digerir els greixos.|The liver makes bile, which helps digest fats.', true, 'Se guarda en la vesícula.|Es guarda en la vesícula.|It is stored in the gall bladder.'),
    ]),
  '3E-BG-9': lesson(['La función de relación permite percibir el entorno y responder. Receptores (órganos de los sentidos) → sistema nervioso (encéfalo, médula, nervios) → efectores (músculos y glándulas). El sistema endocrino coordina con hormonas. El aparato locomotor (huesos y músculos) permite movernos.|La funció de relació permet percebre l’entorn i respondre. Receptors (òrgans dels sentits) → sistema nerviós (encèfal, medul·la, nervis) → efectors (músculs i glàndules). El sistema endocrí coordina amb hormones. L’aparell locomotor (ossos i músculs) permet moure’ns.|Interaction lets us sense our surroundings and respond. Receptors (sense organs) → nervous system (brain, spinal cord, nerves) → effectors (muscles and glands). The endocrine system coordinates with hormones. The musculoskeletal system (bones and muscles) lets us move.'],
    'Retiras la mano al tocar algo que quema. ¿Qué es?|Retires la mà en tocar una cosa que crema. Què és?|You pull your hand away from something hot. What is it?', ['La orden la da la médula espinal, sin pensar.|L’orde la dona la medul·la espinal, sense pensar.|The spinal cord gives the order without thinking.', 'Un acto reflejo.|Un acte reflex.|A reflex action.'], [
      M('¿Qué órgano coordina las funciones del cuerpo?|Quin òrgan coordina les funcions del cos?|Which organ coordinates body functions?', 'el encéfalo|l’encèfal|the brain', ['el estómago|l’estómac|the stomach', 'el corazón|el cor|the heart'], 'Parte del sistema nervioso central.|Part del sistema nerviós central.|Part of the central nervous system.'),
      M('La insulina es una hormona que regula…|La insulina és una hormona que regula…|Insulin is a hormone that controls…', 'la glucosa en sangre|la glucosa en sang|blood sugar', ['el crecimiento del pelo|el creixement dels cabells|hair growth', 'la vista|la vista|eyesight'], 'La produce el páncreas.|La produïx el pàncrees.|The pancreas makes it.'),
      M('Los receptores de la luz están en…|Els receptors de la llum estan en…|Light receptors are in the…', 'la retina|la retina|retina', ['el tímpano|el timpà|eardrum', 'la lengua|la llengua|tongue'], 'Conos y bastones.|Cons i bastons.|Cones and rods.'),
      TF('Los músculos solo pueden tirar, no empujar; por eso trabajan por parejas.|Els músculs només poden estirar, no empényer; per això treballen per parelles.|Muscles can only pull, not push, so they work in pairs.', true, 'Como bíceps y tríceps.|Com bíceps i tríceps.|Like biceps and triceps.'),
      Nq('¿Cuántos huesos tiene aproximadamente un adulto?|Quants ossos té aproximadament un adult?|About how many bones does an adult have?', 206, [106, 300, 52], 'Más de 200.|Més de 200.|Over 200.'),
      M('Las glándulas que producen hormonas forman el sistema…|Les glàndules que produïxen hormones formen el sistema…|Glands that make hormones form the…', 'endocrino|endocrí|endocrine system', ['digestivo|digestiu|digestive system', 'excretor|excretor|excretory system'], 'Las hormonas viajan por la sangre.|Les hormones viatgen per la sang.|Hormones travel in the blood.'),
    ]),
  '3E-BG-10': lesson(['La reproducción humana es sexual: el óvulo y el espermatozoide (gametos) se unen en la fecundación y forman un cigoto, que se divide y se implanta en el útero. El embarazo dura unas 40 semanas. Aparato reproductor femenino: ovarios, trompas, útero, vagina. Masculino: testículos, conductos, próstata, pene.|La reproducció humana és sexual: l’òvul i l’espermatozou (gàmetes) s’unixen en la fecundació i formen un zigot, que es dividix i s’implanta en l’úter. L’embaràs dura unes 40 setmanes. Aparell reproductor femení: ovaris, trompes, úter, vagina. Masculí: testicles, conductes, pròstata, penis.|Human reproduction is sexual: the egg and sperm (gametes) join at fertilisation to form a zygote, which divides and implants in the uterus. Pregnancy lasts about 40 weeks. Female reproductive system: ovaries, fallopian tubes, uterus, vagina. Male: testes, ducts, prostate, penis.'],
    '¿Dónde suele producirse la fecundación?|On sol produir-se la fecundació?|Where does fertilisation usually happen?', ['El óvulo baja desde el ovario.|L’òvul baixa des de l’ovari.|The egg travels from the ovary.', 'En las trompas de Falopio.|En les trompes de Fal·lopi.|In the fallopian tubes.'], [
      M('Los óvulos se producen en los…|Els òvuls es produïxen en els…|Eggs are produced in the…', 'ovarios|ovaris|ovaries', ['testículos|testicles|testes', 'riñones|ronyons|kidneys'], 'Gónadas femeninas.|Gònades femenines.|Female gonads.'),
      M('Los espermatozoides se producen en los…|Els espermatozous es produïxen en els…|Sperm are produced in the…', 'testículos|testicles|testes', ['ovarios|ovaris|ovaries', 'pulmones|pulmons|lungs'], 'Gónadas masculinas.|Gònades masculines.|Male gonads.'),
      M('La célula que resulta de la fecundación es el…|La cèl·lula que resulta de la fecundació és el…|The cell formed at fertilisation is the…', 'cigoto|zigot|zygote', ['óvulo|òvul|egg', 'gameto|gàmeta|gamete'], 'Se divide y forma el embrión.|Es dividix i forma l’embrió.|It divides to form the embryo.'),
      Nq('¿Cuántas semanas dura aproximadamente un embarazo?|Quantes setmanes dura aproximadament un embaràs?|About how many weeks does pregnancy last?', 40, [20, 52, 30], 'Unos nueve meses.|Uns nou mesos.|About nine months.'),
      M('La placenta sirve para…|La placenta servix per a…|The placenta is used to…', 'intercambiar nutrientes y gases entre madre y feto|intercanviar nutrients i gasos entre mare i fetus|exchange nutrients and gases between mother and fetus', ['producir óvulos|produir òvuls|make eggs', 'proteger los huesos|protegir els ossos|protect bones'], 'Unida por el cordón umbilical.|Unida pel cordó umbilical.|Linked by the umbilical cord.'),
      TF('El ciclo menstrual dura aproximadamente 28 días, aunque varía.|El cicle menstrual dura aproximadament 28 dies, encara que varia.|The menstrual cycle lasts about 28 days, though it varies.', true, 'Cada persona es distinta.|Cada persona és diferent.|Everyone is different.'),
    ]),
  '3E-BG-11': lesson(['En la pubertad, las hormonas sexuales producen cambios físicos (crecimiento rápido, vello, desarrollo de los órganos sexuales, voz) y también emocionales y sociales. El ritmo es diferente en cada persona y todo es normal dentro de una gran variedad.|En la pubertat, les hormones sexuals produïxen canvis físics (creixement ràpid, borrissol, desenvolupament dels òrgans sexuals, veu) i també emocionals i socials. El ritme és diferent en cada persona i tot és normal dins d’una gran varietat.|In puberty, sex hormones cause physical changes (growth spurt, body hair, development of sexual organs, voice) as well as emotional and social ones. The pace differs from person to person, and a wide range is normal.'],
    '¿Por qué unos compañeros crecen antes que otros?|Per què uns companys creixen abans que altres?|Why do some classmates grow sooner than others?', ['Las hormonas se activan a edades distintas.|Les hormones s’activen a edats diferents.|Hormones switch on at different ages.', 'Cada cuerpo tiene su ritmo.|Cada cos té el seu ritme.|Each body has its own pace.'], [
      M('¿Qué hormonas producen los cambios de la pubertad?|Quines hormones produïxen els canvis de la pubertat?|Which hormones cause the changes of puberty?', 'las hormonas sexuales (estrógenos, testosterona)|les hormones sexuals (estrògens, testosterona)|sex hormones (oestrogen, testosterone)', ['la insulina|la insulina|insulin', 'la adrenalina|l’adrenalina|adrenaline'], 'Las producen ovarios y testículos.|Les produïxen ovaris i testicles.|Made by the ovaries and testes.'),
      TF('Los cambios emocionales también forman parte de la adolescencia.|Els canvis emocionals també formen part de l’adolescència.|Emotional changes are part of adolescence too.', true, 'Hablar con personas de confianza ayuda.|Parlar amb persones de confiança ajuda.|Talking to trusted people helps.'),
      M('El acné en la adolescencia se debe sobre todo a…|L’acne en l’adolescència es deu sobretot a…|Teenage acne is mainly due to…', 'más grasa en la piel por las hormonas|més greix en la pell per les hormones|more oily skin caused by hormones', ['comer chocolate|menjar xocolate|eating chocolate', 'no dormir|no dormir|not sleeping'], 'Higiene adecuada y paciencia.|Higiene adequada i paciència.|Good hygiene and patience.'),
      TF('Todos los adolescentes deben cambiar exactamente a la misma edad.|Tots els adolescents han de canviar exactament a la mateixa edat.|All teenagers should change at exactly the same age.', false, 'Hay mucha variación normal.|Hi ha molta variació normal.|There is a lot of normal variation.'),
      M('Durante la adolescencia, el sueño recomendado es de…|Durant l’adolescència, la son recomanada és de…|During adolescence, the recommended sleep is…', '8 a 10 horas|8 a 10 hores|8 to 10 hours', ['4 a 5 horas|4 a 5 hores|4 to 5 hours', '12 a 14 horas|12 a 14 hores|12 to 14 hours'], 'El cerebro sigue madurando.|El cervell continua madurant.|The brain is still developing.'),
      M('La glándula que da la orden de iniciar la pubertad es la…|La glàndula que dona l’orde d’iniciar la pubertat és la…|The gland that triggers puberty is the…', 'hipófisis|hipòfisi|pituitary gland', ['tiroides|tiroide|thyroid', 'vesícula|vesícula|gall bladder'], 'Está en la base del encéfalo.|Està en la base de l’encèfal.|It is at the base of the brain.'),
    ]),
  '3E-BG-12': lesson(['La sexualidad incluye afectos, respeto, identidad y comunicación. Una relación sana se basa en el consentimiento, la igualdad y la confianza; nadie debe presionar a otra persona. El preservativo es el único método que protege a la vez del embarazo y de las infecciones de transmisión sexual (ITS).|La sexualitat inclou afectes, respecte, identitat i comunicació. Una relació sana es basa en el consentiment, la igualtat i la confiança; ningú ha de pressionar una altra persona. El preservatiu és l’únic mètode que protegix alhora de l’embaràs i de les infeccions de transmissió sexual (ITS).|Sexuality includes feelings, respect, identity and communication. A healthy relationship is based on consent, equality and trust; nobody should pressure anyone. Condoms are the only method that protects against both pregnancy and sexually transmitted infections (STIs).', 'Ante dudas, se puede acudir a profesionales sanitarios o a centros de salud sexual y reproductiva.|Davant de dubtes, es pot acudir a professionals sanitaris o a centres de salut sexual i reproductiva.|With any questions, you can go to health professionals or sexual health clinics.'],
    '¿Qué es el consentimiento?|Què és el consentiment?|What is consent?', ['Es un «sí» libre, claro y que se puede retirar.|És un «sí» lliure, clar i que es pot retirar.|A free, clear "yes" that can be withdrawn.', 'Sin consentimiento, no hay relación respetuosa.|Sense consentiment, no hi ha relació respectuosa.|Without consent, there is no respectful relationship.'], [
      M('¿Qué método protege de las ITS?|Quin mètode protegix de les ITS?|Which method protects against STIs?', 'el preservativo|el preservatiu|the condom', ['la píldora anticonceptiva|la píndola anticonceptiva|the contraceptive pill', 'ninguno|cap|none'], 'La píldora solo evita el embarazo.|La píndola només evita l’embaràs.|The pill only prevents pregnancy.'),
      TF('Controlar el móvil de la pareja es una muestra de amor.|Controlar el mòbil de la parella és una mostra d’amor.|Checking your partner’s phone is a sign of love.', false, 'Es una conducta de control, no de respeto.|És una conducta de control, no de respecte.|It is controlling behaviour, not respect.'),
      M('Una relación sana se basa en…|Una relació sana es basa en…|A healthy relationship is based on…', 'respeto, confianza e igualdad|respecte, confiança i igualtat|respect, trust and equality', ['celos y control|gelosia i control|jealousy and control', 'obligación|obligació|obligation'], 'Ninguno manda sobre el otro.|Cap no mana sobre l’altre.|Neither controls the other.'),
      TF('Una persona puede cambiar de opinión y retirar su consentimiento en cualquier momento.|Una persona pot canviar d’opinió i retirar el seu consentiment en qualsevol moment.|A person can change their mind and withdraw consent at any time.', true, 'Y hay que respetarlo.|I cal respectar-ho.|And that must be respected.'),
      M('Ante una duda sobre salud sexual, lo mejor es…|Davant d’un dubte sobre salut sexual, el millor és…|With a sexual health question, it is best to…', 'consultar a profesionales sanitarios|consultar professionals sanitaris|ask health professionals', ['fiarse de rumores|fiar-se de rumors|trust rumours', 'no preguntar nunca|no preguntar mai|never ask'], 'Información fiable y confidencial.|Informació fiable i confidencial.|Reliable, confidential information.'),
      TF('Compartir imágenes íntimas de otra persona sin permiso es un delito.|Compartir imatges íntimes d’una altra persona sense permís és un delicte.|Sharing someone’s intimate images without permission is a crime.', true, 'Si te ocurre, cuéntalo a un adulto de confianza.|Si et passa, conta-ho a un adult de confiança.|If it happens to you, tell a trusted adult.'),
    ]),
  '3E-BG-13': lesson(['Enfermedades frecuentes de los aparatos: digestivo (gastroenteritis, caries), respiratorio (asma, gripe, bronquitis), circulatorio (hipertensión, infarto), excretor (cálculos renales), nervioso (migraña). Muchas se previenen con hábitos saludables: dieta, ejercicio, no fumar, higiene.|Malalties freqüents dels aparells: digestiu (gastroenteritis, càries), respiratori (asma, grip, bronquitis), circulatori (hipertensió, infart), excretor (càlculs renals), nerviós (migranya). Moltes es prevenen amb hàbits saludables: dieta, exercici, no fumar, higiene.|Common diseases of the body systems: digestive (gastroenteritis, tooth decay), respiratory (asthma, flu, bronchitis), circulatory (high blood pressure, heart attack), excretory (kidney stones), nervous (migraine). Many are prevented by healthy habits: diet, exercise, not smoking, hygiene.'],
    '¿Cómo se previene la caries?|Com es prevé la càries?|How is tooth decay prevented?', ['Las bacterias de la boca usan el azúcar y producen ácido.|Els bacteris de la boca usen el sucre i produïxen àcid.|Mouth bacteria use sugar and make acid.', 'Cepillado, poco azúcar y revisión dental.|Raspallat, poc sucre i revisió dental.|Brushing, less sugar and dental check-ups.'], [
      M('El tabaco daña sobre todo el aparato…|El tabac danya sobretot l’aparell…|Tobacco mainly damages the…', 'respiratorio y circulatorio|respiratori i circulatori|respiratory and circulatory systems', ['locomotor|locomotor|musculoskeletal system', 'reproductor solo|reproductor només|reproductive system only'], 'Cáncer de pulmón, infartos.|Càncer de pulmó, infarts.|Lung cancer, heart attacks.'),
      M('La hipertensión es…|La hipertensió és…|Hypertension is…', 'tener la presión arterial alta|tindre la pressió arterial alta|high blood pressure', ['tener fiebre|tindre febre|having a fever', 'tener hambre|tindre fam|being hungry'], 'Se relaciona con sal, sedentarismo y estrés.|Es relaciona amb sal, sedentarisme i estrés.|Linked to salt, inactivity and stress.'),
      M('El asma afecta a…|L’asma afecta…|Asthma affects the…', 'los bronquios|els bronquis|airways (bronchi)', ['los riñones|els ronyons|kidneys', 'los huesos|els ossos|bones'], 'Se estrechan y cuesta respirar.|S’estrenyen i costa respirar.|They narrow and breathing is hard.'),
      TF('Beber suficiente agua ayuda a prevenir cálculos renales.|Beure prou aigua ajuda a prevenir càlculs renals.|Drinking enough water helps prevent kidney stones.', true, 'Diluye la orina.|Dilueix l’orina.|It dilutes urine.'),
      M('La gastroenteritis suele causar…|La gastroenteritis sol causar…|Gastroenteritis usually causes…', 'diarrea y vómitos|diarrea i vòmits|diarrhoea and vomiting', ['tos y estornudos|tos i esternuts|coughs and sneezes', 'dolor de rodilla|dolor de genoll|knee pain'], 'Importante hidratarse.|Important hidratar-se.|Drinking fluids is important.'),
      M('Hacer ejercicio con regularidad reduce el riesgo de…|Fer exercici amb regularitat reduïx el risc de…|Regular exercise lowers the risk of…', 'enfermedades cardiovasculares|malalties cardiovasculars|heart and circulatory disease', ['caries|càries|tooth decay', 'miopía|miopia|short-sightedness'], 'Fortalece el corazón.|Enfortix el cor.|It strengthens the heart.'),
    ]),
  '3E-BG-14': lesson(['La OMS define la salud como un estado de bienestar físico, mental y social, no solo la ausencia de enfermedad. Enfermedades infecciosas: las causan microorganismos y se contagian (gripe). No infecciosas: no se contagian (diabetes tipo 2, cáncer). Factores de riesgo: tabaco, alcohol, sedentarismo, mala alimentación.|L’OMS definix la salut com un estat de benestar físic, mental i social, no sols l’absència de malaltia. Malalties infeccioses: les causen microorganismes i es contagien (grip). No infeccioses: no es contagien (diabetis tipus 2, càncer). Factors de risc: tabac, alcohol, sedentarisme, mala alimentació.|The WHO defines health as physical, mental and social wellbeing, not just the absence of disease. Infectious diseases are caused by microorganisms and spread (flu). Non-infectious diseases do not spread (type 2 diabetes, cancer). Risk factors: tobacco, alcohol, inactivity, poor diet.'],
    '¿La diabetes tipo 2 se contagia?|La diabetis tipus 2 es contagia?|Is type 2 diabetes contagious?', ['No la causa un microorganismo.|No la causa un microorganisme.|It is not caused by a microorganism.', 'No: es no infecciosa.|No: és no infecciosa.|No: it is non-infectious.'], [
      M('¿Qué enfermedad es infecciosa?|Quina malaltia és infecciosa?|Which disease is infectious?', 'la gripe|la grip|flu', ['la diabetes|la diabetis|diabetes', 'la miopía|la miopia|short-sightedness'], 'La causa un virus.|La causa un virus.|A virus causes it.'),
      M('Los antibióticos sirven contra…|Els antibiòtics servixen contra…|Antibiotics work against…', 'bacterias|bacteris|bacteria', ['virus|virus|viruses', 'todas las enfermedades|totes les malalties|all diseases'], 'No curan la gripe ni el resfriado.|No curen la grip ni el refredat.|They do not cure flu or colds.'),
      TF('La salud mental forma parte de la salud.|La salut mental forma part de la salut.|Mental health is part of health.', true, 'Según la definición de la OMS.|Segons la definició de l’OMS.|According to the WHO definition.'),
      M('Usar antibióticos sin necesidad favorece…|Usar antibiòtics sense necessitat afavorix…|Using antibiotics unnecessarily encourages…', 'bacterias resistentes|bacteris resistents|resistant bacteria', ['huesos fuertes|ossos forts|strong bones', 'mejor vista|millor vista|better eyesight'], 'Luego dejan de funcionar.|Després deixen de funcionar.|Then they stop working.'),
      M('Un factor de riesgo de enfermedad cardiovascular es…|Un factor de risc de malaltia cardiovascular és…|A risk factor for heart disease is…', 'el sedentarismo|el sedentarisme|lack of exercise', ['beber agua|beure aigua|drinking water', 'dormir bien|dormir bé|sleeping well'], 'Moverse es salud.|Moure’s és salut.|Moving is healthy.'),
      M('La tuberculosis la causa…|La tuberculosi la causa…|Tuberculosis is caused by…', 'una bacteria|un bacteri|a bacterium', ['un virus|un virus|a virus', 'una mala postura|una mala postura|bad posture'], 'Se trata con antibióticos.|Es tracta amb antibiòtics.|It is treated with antibiotics.'),
    ]),
  '3E-BG-15': lesson(['El sistema inmunitario nos defiende: barreras (piel, mucosas), defensas inespecíficas (fiebre, inflamación, fagocitos) y específicas (linfocitos que producen anticuerpos y guardan memoria). Las vacunas entrenan la memoria inmunitaria sin pasar la enfermedad. Vacunarse protege también a quien no puede (inmunidad de grupo).|El sistema immunitari ens defensa: barreres (pell, mucoses), defenses inespecífiques (febre, inflamació, fagòcits) i específiques (limfòcits que produïxen anticossos i guarden memòria). Les vacunes entrenen la memòria immunitària sense passar la malaltia. Vacunar-se protegix també qui no pot (immunitat de grup).|The immune system defends us: barriers (skin, mucous membranes), non-specific defences (fever, inflammation, phagocytes) and specific ones (lymphocytes that make antibodies and keep a memory). Vaccines train immune memory without the disease. Vaccination also protects those who cannot be vaccinated (herd immunity).'],
    '¿Cómo funciona una vacuna?|Com funciona una vacuna?|How does a vaccine work?', ['Muestra al cuerpo un antígeno inofensivo del microbio.|Mostra al cos un antigen inofensiu del microbi.|It shows the body a harmless antigen from the germ.', 'Se crean anticuerpos y memoria: si llega el microbio, se reacciona rápido.|Es creen anticossos i memòria: si arriba el microbi, es reacciona ràpid.|Antibodies and memory form: if the germ arrives, the response is fast.'], [
      M('Los anticuerpos los producen los…|Els anticossos els produïxen els…|Antibodies are made by…', 'linfocitos|limfòcits|lymphocytes', ['glóbulos rojos|glòbuls rojos|red blood cells', 'plaquetas|plaquetes|platelets'], 'Un tipo de glóbulo blanco.|Un tipus de glòbul blanc.|A type of white blood cell.'),
      M('La primera barrera contra los microbios es…|La primera barrera contra els microbis és…|The first barrier against germs is…', 'la piel|la pell|the skin', ['el corazón|el cor|the heart', 'el estómago vacío|l’estómac buit|an empty stomach'], 'Y las mucosas.|I les mucoses.|And mucous membranes.'),
      TF('La inmunidad de grupo protege a personas que no pueden vacunarse.|La immunitat de grup protegix persones que no es poden vacunar.|Herd immunity protects people who cannot be vaccinated.', true, 'Si casi todos están vacunados, el microbio no circula.|Si quasi tots estan vacunats, el microbi no circula.|If nearly everyone is vaccinated, the germ cannot spread.'),
      M('La fiebre es…|La febre és…|Fever is…', 'una defensa del cuerpo|una defensa del cos|a defence of the body', ['siempre una enfermedad grave|sempre una malaltia greu|always a serious disease', 'un tipo de vacuna|un tipus de vacuna|a type of vaccine'], 'Dificulta la vida del microbio.|Dificulta la vida del microbi.|It makes life hard for the germ.'),
      TF('Las vacunas causan la enfermedad que previenen.|Les vacunes causen la malaltia que prevenen.|Vaccines cause the disease they prevent.', false, 'Usan antígenos inofensivos.|Usen antígens inofensius.|They use harmless antigens.'),
      M('Una alergia es…|Una al·lèrgia és…|An allergy is…', 'una reacción exagerada a algo inofensivo|una reacció exagerada a una cosa inofensiva|an over-reaction to something harmless', ['falta de vitaminas|falta de vitamines|a vitamin shortage', 'una infección|una infecció|an infection'], 'Polen, ácaros, alimentos…|Pol·len, àcars, aliments…|Pollen, dust mites, foods…'),
    ]),
  '3E-BG-16': lesson(['La homeostasis es la capacidad del cuerpo de mantener estable su medio interno: temperatura (~37 °C), glucosa en sangre, agua y sales, pH. Lo regulan el sistema nervioso y el endocrino. Ejemplos: sudar para enfriarnos, tiritar para calentarnos, la insulina baja la glucosa.|L’homeòstasi és la capacitat del cos de mantindre estable el seu medi intern: temperatura (~37 °C), glucosa en sang, aigua i sals, pH. Ho regulen el sistema nerviós i l’endocrí. Exemples: suar per a refredar-nos, tremolar per a escalfar-nos, la insulina baixa la glucosa.|Homeostasis is the body’s ability to keep its internal environment stable: temperature (~37 °C), blood sugar, water and salts, pH. The nervous and endocrine systems control it. Examples: sweating to cool down, shivering to warm up, insulin lowering blood sugar.'],
    '¿Por qué sudamos al hacer deporte?|Per què suem en fer esport?|Why do we sweat when exercising?', ['El ejercicio produce calor.|L’exercici produïx calor.|Exercise produces heat.', 'El sudor, al evaporarse, enfría la piel.|La suor, en evaporar-se, refreda la pell.|Sweat cools the skin as it evaporates.'], [
      M('Tiritar de frío sirve para…|Tremolar de fred servix per a…|Shivering helps to…', 'producir calor con los músculos|produir calor amb els músculs|make heat with the muscles', ['enfriarse|refredar-se|cool down', 'dormir|dormir|sleep'], 'Contracciones rápidas.|Contraccions ràpides.|Fast contractions.'),
      M('Tras comer, la glucosa sube y el páncreas libera…|Després de menjar, la glucosa puja i el pàncrees allibera…|After eating, blood sugar rises and the pancreas releases…', 'insulina|insulina|insulin', ['adrenalina|adrenalina|adrenaline', 'saliva|saliva|saliva'], 'Hace que las células tomen glucosa.|Fa que les cèl·lules prenguen glucosa.|It makes cells take up glucose.'),
      Nq('¿Temperatura corporal normal aproximada (°C)?|Temperatura corporal normal aproximada (°C)?|Approximate normal body temperature (°C)?', 37, [40, 33, 36], 'Entre 36 y 37 °C.|Entre 36 i 37 °C.|Between 36 and 37 °C.'),
      TF('Si bebemos poca agua, los riñones producen orina más concentrada.|Si bevem poca aigua, els ronyons produïxen orina més concentrada.|If we drink little water, the kidneys make more concentrated urine.', true, 'Ahorran agua.|Estalvien aigua.|They save water.'),
      M('En la diabetes tipo 1, el cuerpo no produce suficiente…|En la diabetis tipus 1, el cos no produïx prou…|In type 1 diabetes, the body does not make enough…', 'insulina|insulina|insulin', ['hemoglobina|hemoglobina|haemoglobin', 'saliva|saliva|saliva'], 'Hay que administrarla.|Cal administrar-la.|It must be given.'),
      M('Con calor, los vasos de la piel se dilatan para…|Amb calor, els vasos de la pell es dilaten per a…|When hot, skin blood vessels widen to…', 'perder calor|perdre calor|lose heat', ['guardar calor|guardar calor|keep heat in', 'producir sudor rojo|produir suor roja|make red sweat'], 'Por eso nos ponemos rojos.|Per això ens posem rojos.|That is why we go red.'),
    ]),
  '3E-BG-17': lesson(['Las sustancias adictivas (tabaco, alcohol, cannabis, otras drogas) y también algunas conductas (apuestas, uso excesivo de pantallas) pueden crear dependencia. Dañan el cerebro en desarrollo, la salud física, los estudios y las relaciones. Ante un problema, pedir ayuda es un paso valiente.|Les substàncies addictives (tabac, alcohol, cànnabis, altres drogues) i també algunes conductes (apostes, ús excessiu de pantalles) poden crear dependència. Danyen el cervell en desenvolupament, la salut física, els estudis i les relacions. Davant d’un problema, demanar ajuda és un pas valent.|Addictive substances (tobacco, alcohol, cannabis, other drugs) and some behaviours (gambling, excessive screen use) can create dependence. They harm the developing brain, physical health, studies and relationships. If there is a problem, asking for help is a brave step.'],
    '¿Por qué el alcohol es especialmente dañino en la adolescencia?|Per què l’alcohol és especialment nociu en l’adolescència?|Why is alcohol especially harmful in adolescence?', ['El cerebro madura hasta los 25 años aproximadamente.|El cervell madura fins als 25 anys aproximadament.|The brain matures until about age 25.', 'El alcohol interfiere en ese desarrollo.|L’alcohol interferix en eixe desenvolupament.|Alcohol interferes with that development.'], [
      M('La sustancia adictiva del tabaco es…|La substància addictiva del tabac és…|The addictive substance in tobacco is…', 'la nicotina|la nicotina|nicotine', ['la cafeína|la cafeïna|caffeine', 'la vitamina C|la vitamina C|vitamin C'], 'Crea dependencia rápido.|Crea dependència ràpid.|It is quickly addictive.'),
      TF('Los vapeadores también contienen sustancias perjudiciales.|Els vapejadors també contenen substàncies perjudicials.|Vapes also contain harmful substances.', true, 'Muchos llevan nicotina.|Molts porten nicotina.|Many contain nicotine.'),
      M('La adicción a las apuestas es…|L’addicció a les apostes és…|Gambling addiction is…', 'una adicción sin sustancia|una addicció sense substància|an addiction without a substance', ['un deporte|un esport|a sport', 'una forma segura de ganar dinero|una manera segura de guanyar diners|a safe way to make money'], 'A la larga, la casa siempre gana.|A la llarga, la casa sempre guanya.|In the long run, the house always wins.'),
      M('Una señal de uso problemático de pantallas es…|Un senyal d’ús problemàtic de pantalles és…|A sign of problematic screen use is…', 'dejar de dormir o de estudiar por usarlas|deixar de dormir o d’estudiar per usar-les|losing sleep or study time to them', ['usarlas para un trabajo de clase|usar-les per a un treball de classe|using them for homework', 'llamar a la familia|telefonar a la família|calling family'], 'Cuando interfiere en la vida diaria.|Quan interferix en la vida diària.|When it interferes with daily life.'),
      TF('Pedir ayuda ante una adicción es señal de debilidad.|Demanar ajuda davant d’una addicció és senyal de debilitat.|Asking for help with an addiction is a sign of weakness.', false, 'Es valiente y necesario.|És valent i necessari.|It is brave and necessary.'),
      M('Conducir tras beber alcohol es peligroso porque…|Conduir després de beure alcohol és perillós perquè…|Driving after drinking is dangerous because…', 'reduce los reflejos y la atención|reduïx els reflexos i l’atenció|it slows reflexes and attention', ['mejora la vista|millora la vista|it improves eyesight', 'no afecta|no afecta|it has no effect'], 'Causa muchos accidentes.|Causa molts accidents.|It causes many accidents.'),
    ]),
  '3E-BG-18': lesson(['Los procesos geológicos externos (meteorización, erosión, transporte y sedimentación) los producen el agua, el viento, el hielo, la gravedad y los seres vivos, con la energía del Sol. Crean formas como valles, cañones, playas, deltas, cuevas y dunas.|Els processos geològics externs (meteorització, erosió, transport i sedimentació) els produïxen l’aigua, el vent, el gel, la gravetat i els éssers vius, amb l’energia del Sol. Creen formes com valls, canyons, platges, deltes, coves i dunes.|External geological processes (weathering, erosion, transport and deposition) are driven by water, wind, ice, gravity and living things, powered by the Sun. They create valleys, canyons, beaches, deltas, caves and dunes.'],
    '¿Cómo se forma una playa de arena?|Com es forma una platja d’arena?|How does a sandy beach form?', ['Ríos y olas transportan arena.|Rius i ones transporten arena.|Rivers and waves carry sand.', 'Se deposita donde el agua pierde fuerza: sedimentación.|Es diposita on l’aigua perd força: sedimentació.|It is dropped where the water slows: deposition.'], [
      M('El agente geológico más importante en el modelado del relieve es…|L’agent geològic més important en el modelatge del relleu és…|The most important agent shaping the land is…', 'el agua|l’aigua|water', ['el viento|el vent|wind', 'el fuego|el foc|fire'], 'Ríos, lluvia, mar, hielo.|Rius, pluja, mar, gel.|Rivers, rain, sea, ice.'),
      M('Los acantilados se forman por…|Els penya-segats es formen per…|Sea cliffs form by…', 'la erosión de las olas|l’erosió de les ones|wave erosion', ['volcanes|volcans|volcanoes', 'el viento del desierto|el vent del desert|desert wind'], 'El mar golpea la costa.|La mar colpeja la costa.|The sea pounds the coast.'),
      TF('Las estalactitas crecen hacia abajo desde el techo de las cuevas.|Les estalactites creixen cap avall des del sostre de les coves.|Stalactites grow down from cave ceilings.', true, 'Las estalagmitas crecen desde el suelo.|Les estalagmites creixen des del sòl.|Stalagmites grow up from the floor.'),
      M('Un desprendimiento de rocas por una ladera se debe a…|Un despreniment de roques per un vessant es deu a…|A rockfall down a slope is caused by…', 'la gravedad|la gravetat|gravity', ['el magnetismo|el magnetisme|magnetism', 'la luz|la llum|light'], 'Proceso gravitacional.|Procés gravitacional.|A gravity-driven process.'),
      M('Los ríos en su curso alto forman valles en forma de…|Els rius en el seu curs alt formen valls en forma de…|In their upper course, rivers form valleys shaped like a…', 'V|V|V', ['U|U|U', 'O|O|O'], 'Erosionan hacia abajo.|Erosionen cap avall.|They cut downwards.'),
      M('La energía que mueve los procesos externos procede de…|L’energia que mou els processos externs procedix de…|The energy driving external processes comes from…', 'el Sol|el Sol|the Sun', ['el núcleo terrestre|el nucli terrestre|the Earth’s core', 'la Luna|la Lluna|the Moon'], 'Evapora el agua y mueve el aire.|Evapora l’aigua i mou l’aire.|It evaporates water and moves air.'),
    ]),
  '3E-BG-19': lesson(['La energía interna de la Tierra procede del calor del núcleo y de la desintegración radiactiva. Provoca corrientes en el manto que mueven las placas litosféricas. Consecuencias: terremotos, volcanes, formación de montañas (orogénesis) y deriva continental.|L’energia interna de la Terra procedix de la calor del nucli i de la desintegració radioactiva. Provoca corrents en el mantell que mouen les plaques litosfèriques. Conseqüències: terratrémols, volcans, formació de muntanyes (orogènesi) i deriva continental.|The Earth’s internal energy comes from heat in the core and radioactive decay. It drives currents in the mantle that move lithospheric plates. Results: earthquakes, volcanoes, mountain building (orogeny) and continental drift.'],
    '¿Qué mueve las placas tectónicas?|Què mou les plaques tectòniques?|What moves tectonic plates?', ['El manto caliente se mueve muy lentamente.|El mantell calent es mou molt lentament.|The hot mantle moves very slowly.', 'Corrientes de convección en el manto.|Corrents de convecció en el mantell.|Convection currents in the mantle.'], [
      M('¿Quién propuso la deriva continental?|Qui va proposar la deriva continental?|Who proposed continental drift?', 'Alfred Wegener|Alfred Wegener|Alfred Wegener', ['Charles Darwin|Charles Darwin|Charles Darwin', 'Isaac Newton|Isaac Newton|Isaac Newton'], 'En 1912.|El 1912.|In 1912.'),
      M('Una prueba de la deriva continental es…|Una prova de la deriva continental és…|One piece of evidence for continental drift is…', 'el encaje de las costas de África y Sudamérica|l’encaix de les costes d’Àfrica i Sud-amèrica|how Africa and South America fit together', ['la forma de la Luna|la forma de la Lluna|the Moon’s shape', 'la altura del Everest|l’altura de l’Everest|Everest’s height'], 'Y fósiles iguales en ambos continentes.|I fòssils iguals en tots dos continents.|And matching fossils on both continents.'),
      Nq('¿Cuántos cm por año se mueven las placas, aproximadamente (escoge el valor típico)?|Quants cm per any es mouen les plaques, aproximadament (tria el valor típic)?|About how many cm a year do plates move (choose the typical value)?', 3, [300, 30, 0], 'Como crecen las uñas.|Com creixen les ungles.|About as fast as fingernails grow.'),
      TF('Pangea fue un supercontinente que reunía casi todas las tierras.|Pangea va ser un supercontinent que reunia quasi totes les terres.|Pangaea was a supercontinent joining almost all land.', true, 'Hace unos 250 millones de años.|Fa uns 250 milions d’anys.|About 250 million years ago.'),
      M('Las dorsales oceánicas son zonas donde las placas…|Les dorsals oceàniques són zones on les plaques…|Mid-ocean ridges are where plates…', 'se separan y se crea corteza nueva|se separen i es crea escorça nova|move apart and new crust forms', ['chocan y se destruyen|xoquen i es destruïxen|collide and are destroyed', 'no se mueven|no es mouen|do not move'], 'Sale magma.|Ix magma.|Magma rises.'),
      M('El Himalaya se formó por el choque de…|L’Himàlaia es va formar pel xoc de…|The Himalayas formed from the collision of…', 'la India con Asia|l’Índia amb Àsia|India and Asia', ['África con América|Àfrica amb Amèrica|Africa and America', 'dos océanos|dos oceans|two oceans'], 'Dos placas continentales.|Dues plaques continentals.|Two continental plates.'),
    ]),
  '3E-BG-20': lesson(['La atmósfera y la hidrosfera interaccionan: el ciclo del agua y la circulación del aire distribuyen el calor y forman el clima. El tiempo atmosférico (lo que pasa hoy) es distinto del clima (la media de muchos años). Ambas se contaminan: humos, gases, vertidos y plásticos.|L’atmosfera i la hidrosfera interaccionen: el cicle de l’aigua i la circulació de l’aire distribuïxen la calor i formen el clima. El temps atmosfèric (el que passa hui) és diferent del clima (la mitjana de molts anys). Totes dues es contaminen: fums, gasos, abocaments i plàstics.|The atmosphere and hydrosphere interact: the water cycle and air circulation spread heat and shape the climate. Weather (what happens today) differs from climate (the average over many years). Both get polluted: smoke, gases, spills and plastics.'],
    '«Hoy llueve en Valencia» ¿es tiempo o clima?|«Hui plou a València» és temps o clima?|"It is raining in Valencia today": weather or climate?', ['Habla de un día concreto.|Parla d’un dia concret.|It describes one day.', 'Tiempo atmosférico.|Temps atmosfèric.|Weather.'], [
      M('El clima mediterráneo tiene…|El clima mediterrani té…|The Mediterranean climate has…', 'veranos secos y calurosos|estius secs i calorosos|hot, dry summers', ['lluvias todo el año|pluges tot l’any|rain all year round', 'nieve permanente|neu permanent|permanent snow'], 'Lluvias en otoño y primavera.|Pluges a la tardor i a la primavera.|Rain in autumn and spring.'),
      M('Las corrientes oceánicas…|Els corrents oceànics…|Ocean currents…', 'reparten el calor por el planeta|repartixen la calor pel planeta|spread heat around the planet', ['solo mueven barcos|només mouen vaixells|only move ships', 'no influyen en el clima|no influïxen en el clima|do not affect climate'], 'Como la corriente del Golfo.|Com el corrent del Golf.|Like the Gulf Stream.'),
      TF('El agua del mar regula la temperatura de las zonas costeras.|L’aigua de la mar regula la temperatura de les zones costaneres.|The sea moderates coastal temperatures.', true, 'Se calienta y enfría despacio.|S’escalfa i es refreda a poc a poc.|It warms and cools slowly.'),
      M('La lluvia ácida se forma por gases como…|La pluja àcida es forma per gasos com…|Acid rain forms from gases such as…', 'óxidos de azufre y nitrógeno|òxids de sofre i nitrogen|sulfur and nitrogen oxides', ['oxígeno|oxigen|oxygen', 'helio|heli|helium'], 'Procedentes de la combustión.|Procedents de la combustió.|From combustion.'),
      M('La «isla de calor» urbana significa que las ciudades…|L’«illa de calor» urbana significa que les ciutats…|The urban "heat island" means cities…', 'están más calientes que el campo|estan més calentes que el camp|are warmer than the countryside', ['están más frías|estan més fredes|are colder', 'tienen más lluvia de nieve|tenen més neu|get more snow'], 'Asfalto, edificios y tráfico.|Asfalt, edificis i trànsit.|Tarmac, buildings and traffic.'),
      TF('Un día frío demuestra que no existe el cambio climático.|Un dia fred demostra que no existix el canvi climàtic.|One cold day proves climate change is not real.', false, 'El clima se mide en décadas, no en días.|El clima es mesura en dècades, no en dies.|Climate is measured over decades, not days.'),
    ]),
  '3E-BG-21': lesson(['El suelo es la capa superficial formada por minerales, materia orgánica (humus), agua, aire y seres vivos. Se forma muy lentamente por la meteorización de la roca y la acción de los seres vivos. Tiene horizontes (capas). Es un recurso no renovable a escala humana: hay que protegerlo de la erosión y la contaminación.|El sòl és la capa superficial formada per minerals, matèria orgànica (humus), aigua, aire i éssers vius. Es forma molt lentament per la meteorització de la roca i l’acció dels éssers vius. Té horitzons (capes). És un recurs no renovable a escala humana: cal protegir-lo de l’erosió i la contaminació.|Soil is the surface layer made of minerals, organic matter (humus), water, air and living things. It forms very slowly from weathered rock and the action of living things. It has horizons (layers). It is non-renewable on a human timescale and must be protected from erosion and pollution.'],
    '¿Qué hacen las lombrices en el suelo?|Què fan els cucs en el sòl?|What do earthworms do in soil?', ['Mezclan la materia orgánica y crean galerías.|Mesclen la matèria orgànica i creen galeries.|They mix in organic matter and make tunnels.', 'Airean y fertilizan el suelo.|Airegen i fertilitzen el sòl.|They aerate and enrich the soil.'], [
      M('El humus es…|L’humus és…|Humus is…', 'materia orgánica descompuesta|matèria orgànica descomposta|decomposed organic matter', ['una roca|una roca|a rock', 'un tipo de agua|un tipus d’aigua|a kind of water'], 'Da fertilidad.|Dona fertilitat.|It makes soil fertile.'),
      M('La vegetación protege el suelo de…|La vegetació protegix el sòl de…|Plants protect soil from…', 'la erosión|l’erosió|erosion', ['la lluvia beneficiosa|la pluja beneficiosa|helpful rain', 'el sol de invierno|el sol d’hivern|winter sunshine'], 'Las raíces lo sujetan.|Les arrels el subjecten.|Roots hold it in place.'),
      TF('Tras un incendio forestal aumenta el riesgo de erosión.|Després d’un incendi forestal augmenta el risc d’erosió.|After a forest fire the risk of erosion rises.', true, 'Sin plantas, la lluvia arrastra el suelo.|Sense plantes, la pluja arrossega el sòl.|Without plants, rain washes soil away.'),
      M('Las capas del suelo se llaman…|Les capes del sòl s’anomenen…|The layers of soil are called…', 'horizontes|horitzons|horizons', ['estratos de hielo|estrats de gel|ice layers', 'placas|plaques|plates'], 'A, B, C…|A, B, C…|A, B, C…'),
      M('Una relación entre seres vivos del suelo y las plantas es…|Una relació entre éssers vius del sòl i les plantes és…|A relationship between soil organisms and plants is…', 'las micorrizas (hongos que ayudan a las raíces)|les micorizes (fongs que ajuden les arrels)|mycorrhizae (fungi helping roots)', ['la fotosíntesis del hongo|la fotosíntesi del fong|fungal photosynthesis', 'ninguna|cap|none'], 'Mutualismo.|Mutualisme.|Mutualism.'),
      TF('El suelo se regenera en pocos años.|El sòl es regenera en pocs anys.|Soil regenerates in a few years.', false, 'Puede tardar siglos.|Pot tardar segles.|It can take centuries.'),
    ]),
  '3E-BG-22': lesson(['La historia de la Tierra se divide en eones (Hádico, Arcaico, Proterozoico, Fanerozoico) y eras (Paleozoica, Mesozoica, Cenozoica). Se data con fósiles, con el orden de los estratos y con métodos radiométricos. Grandes extinciones marcan los cambios de era.|La història de la Terra es dividix en eons (Hàdic, Arcaic, Proterozoic, Fanerozoic) i eres (Paleozoica, Mesozoica, Cenozoica). Es data amb fòssils, amb l’ordre dels estrats i amb mètodes radiomètrics. Grans extincions marquen els canvis d’era.|Earth’s history is divided into eons (Hadean, Archean, Proterozoic, Phanerozoic) and eras (Palaeozoic, Mesozoic, Cenozoic). Dating uses fossils, the order of rock layers and radiometric methods. Mass extinctions mark the change of eras.'],
    '¿Qué marcó el final del Mesozoico?|Què va marcar el final del Mesozoic?|What marked the end of the Mesozoic?', ['Hace 66 millones de años.|Fa 66 milions d’anys.|66 million years ago.', 'Un meteorito y la extinción de los dinosaurios no avianos.|Un meteorit i l’extinció dels dinosaures no avians.|A meteorite and the extinction of non-bird dinosaurs.'], [
      M('Los primeros seres vivos aparecieron en el…|Els primers éssers vius van aparéixer en l’…|The first living things appeared in the…', 'Arcaico|Arcaic|Archean eon', ['Cenozoico|Cenozoic|Cenozoic era', 'Mesozoico|Mesozoic|Mesozoic era'], 'Hace más de 3 500 millones de años.|Fa més de 3 500 milions d’anys.|Over 3.5 billion years ago.'),
      M('La «explosión cámbrica» fue…|L’«explosió cambriana» va ser…|The "Cambrian explosion" was…', 'una rápida diversificación de animales|una ràpida diversificació d’animals|a rapid spread of animal diversity', ['una erupción volcánica|una erupció volcànica|a volcanic eruption', 'el choque de un meteorito|el xoc d’un meteorit|a meteorite impact'], 'Inicio del Paleozoico.|Inici del Paleozoic.|Start of the Palaeozoic.'),
      TF('Los métodos radiométricos permiten saber la edad en años de algunas rocas.|Els mètodes radiomètrics permeten saber l’edat en anys d’algunes roques.|Radiometric methods give the age in years of some rocks.', true, 'Usan isótopos radiactivos.|Usen isòtops radioactius.|They use radioactive isotopes.'),
      M('¿En qué era aparecieron los primeros homínidos?|En quina era van aparéixer els primers homínids?|In which era did the first hominins appear?', 'Cenozoica|Cenozoica|Cenozoic', ['Paleozoica|Paleozoica|Palaeozoic', 'Mesozoica|Mesozoica|Mesozoic'], 'Hace unos 6-7 millones de años.|Fa uns 6-7 milions d’anys.|About 6–7 million years ago.'),
      M('Los trilobites son fósiles típicos del…|Els trilobits són fòssils típics del…|Trilobites are typical fossils of the…', 'Paleozoico|Paleozoic|Palaeozoic', ['Cenozoico|Cenozoic|Cenozoic', 'Mesozoico|Mesozoic|Mesozoic'], 'Artrópodos marinos antiguos.|Artròpodes marins antics.|Ancient marine arthropods.'),
      M('Los ammonites son fósiles guía del…|Els ammonits són fòssils guia del…|Ammonites are index fossils of the…', 'Mesozoico|Mesozoic|Mesozoic', ['Cenozoico|Cenozoic|Cenozoic', 'Arcaico|Arcaic|Archean'], 'Moluscos con concha en espiral.|Mol·luscs amb closca en espiral.|Molluscs with spiral shells.'),
    ]),
  '3E-BG-23': lesson(['Un riesgo geológico depende de la peligrosidad (probabilidad del fenómeno), la vulnerabilidad (daños que puede causar) y la exposición (personas y bienes afectados). En la Comunitat Valenciana destacan las inundaciones, la sismicidad moderada en el sur y los deslizamientos.|Un risc geològic depén de la perillositat (probabilitat del fenomen), la vulnerabilitat (danys que pot causar) i l’exposició (persones i béns afectats). A la Comunitat Valenciana destaquen les inundacions, la sismicitat moderada en el sud i les esllavissades.|A geological risk depends on hazard (likelihood of the event), vulnerability (damage it may cause) and exposure (people and property affected). In the Valencia region, floods, moderate earthquakes in the south and landslides stand out.'],
    '¿Cómo se reduce el riesgo de inundación?|Com es reduïx el risc d’inundació?|How can flood risk be reduced?', ['No construir en zonas inundables.|No construir en zones inundables.|Do not build on flood plains.', 'Planes de emergencia, encauzamientos y alertas.|Plans d’emergència, encauzaments i alertes.|Emergency plans, channels and warnings.'], [
      M('La vulnerabilidad de una ciudad ante un terremoto baja si…|La vulnerabilitat d’una ciutat davant d’un terratrémol baixa si…|A city’s vulnerability to earthquakes drops if…', 'sus edificios son antisísmicos|els seus edificis són antisísmics|its buildings are earthquake-proof', ['tiene muchos habitantes|té molts habitants|it has many people', 'está en una falla activa|està en una falla activa|it sits on an active fault'], 'Menos daños.|Menys danys.|Less damage.'),
      M('La zona de la Comunitat Valenciana con más actividad sísmica es…|La zona de la Comunitat Valenciana amb més activitat sísmica és…|The most seismically active part of the Valencia region is…', 'la Vega Baja (sur de Alicante)|la Vega Baixa (sud d’Alacant)|the Vega Baja (south Alicante)', ['Morella|Morella|Morella', 'L’Albufera|l’Albufera|L’Albufera'], 'Terremoto de Torrevieja de 1829.|Terratrémol de Torrevella de 1829.|The 1829 Torrevieja earthquake.'),
      TF('Ante un aviso rojo por lluvias, hay que evitar pasar por barrancos y pasos inundados.|Davant d’un avís roig per pluges, cal evitar passar per barrancs i passos inundats.|With a red rain warning, avoid ravines and flooded crossings.', true, 'El agua arrastra coches.|L’aigua arrossega cotxes.|Water can sweep cars away.'),
      M('La peligrosidad de un riesgo es…|La perillositat d’un risc és…|The hazard of a risk is…', 'la probabilidad de que ocurra el fenómeno|la probabilitat que ocórrega el fenomen|the likelihood of the event', ['el número de habitantes|el nombre d’habitants|the number of residents', 'el coste de un seguro|el cost d’una assegurança|the cost of insurance'], 'Y su intensidad.|I la seua intensitat.|And its intensity.'),
      M('Una medida de prevención ante deslizamientos es…|Una mesura de prevenció davant d’esllavissades és…|One way to prevent landslides is…', 'reforestar las laderas|reforestar els vessants|replanting slopes', ['talar los árboles|talar els arbres|cutting down trees', 'cargar más peso arriba|carregar més pes dalt|adding weight at the top'], 'Las raíces fijan el terreno.|Les arrels fixen el terreny.|Roots hold the ground.'),
      M('La exposición al riesgo aumenta cuando…|L’exposició al risc augmenta quan…|Exposure to risk increases when…', 'más personas viven en la zona peligrosa|més persones viuen en la zona perillosa|more people live in the danger zone', ['se construyen diques|es construïxen dics|dykes are built', 'hay planes de evacuación|hi ha plans d’evacuació|there are evacuation plans'], 'Más gente, más bienes en riesgo.|Més gent, més béns en risc.|More people and property at risk.'),
    ]),
  '3E-BG-24': lesson(['Los ciclos biogeoquímicos (carbono, nitrógeno, agua, fósforo) reciclan la materia entre seres vivos, atmósfera, hidrosfera y geosfera. La energía, en cambio, fluye: entra como luz y sale como calor. Las actividades humanas alteran estos ciclos (más CO₂, exceso de nitratos).|Els cicles biogeoquímics (carboni, nitrogen, aigua, fòsfor) reciclen la matèria entre éssers vius, atmosfera, hidrosfera i geosfera. L’energia, en canvi, flueix: entra com a llum i ix com a calor. Les activitats humanes alteren estos cicles (més CO₂, excés de nitrats).|Biogeochemical cycles (carbon, nitrogen, water, phosphorus) recycle matter between living things, atmosphere, hydrosphere and geosphere. Energy, however, flows: it enters as light and leaves as heat. Human activities upset these cycles (more CO₂, excess nitrates).'],
    '¿Cómo entra el carbono en los seres vivos?|Com entra el carboni en els éssers vius?|How does carbon enter living things?', ['Las plantas toman CO₂ del aire.|Les plantes prenen CO₂ de l’aire.|Plants take CO₂ from the air.', 'Lo fijan en la fotosíntesis.|El fixen en la fotosíntesi.|They fix it in photosynthesis.'], [
      M('Las bacterias fijadoras de nitrógeno viven en las raíces de…|Els bacteris fixadors de nitrogen viuen en les arrels de…|Nitrogen-fixing bacteria live in the roots of…', 'las leguminosas|les lleguminoses|legumes', ['los pinos|els pins|pine trees', 'los cactus|els cactus|cacti'], 'Judías, garbanzos, alfalfa.|Fesols, cigrons, alfals.|Beans, chickpeas, alfalfa.'),
      M('La quema de combustibles fósiles devuelve a la atmósfera…|La crema de combustibles fòssils torna a l’atmosfera…|Burning fossil fuels returns to the atmosphere…', 'carbono que estaba enterrado|carboni que estava soterrat|carbon that was buried', ['nitrógeno puro|nitrogen pur|pure nitrogen', 'oxígeno|oxigen|oxygen'], 'Aumenta el CO₂.|Augmenta el CO₂.|It raises CO₂.'),
      TF('Los océanos absorben parte del CO₂ que emitimos.|Els oceans absorbixen part del CO₂ que emetem.|Oceans absorb some of the CO₂ we emit.', true, 'Y se acidifican.|I s’acidifiquen.|And they become more acidic.'),
      M('El exceso de nitratos en ríos y lagos provoca…|L’excés de nitrats en rius i llacs provoca…|Too many nitrates in rivers and lakes cause…', 'eutrofización (exceso de algas y falta de oxígeno)|eutrofització (excés d’algues i falta d’oxigen)|eutrophication (algal blooms and lack of oxygen)', ['agua más limpia|aigua més neta|cleaner water', 'más peces siempre|més peixos sempre|always more fish'], 'Le pasó al Mar Menor.|Li va passar al Mar Menor.|It happened in the Mar Menor.'),
      M('La materia en un ecosistema…|La matèria en un ecosistema…|Matter in an ecosystem…', 'se recicla en ciclos|es recicla en cicles|is recycled in cycles', ['se pierde como calor|es perd com a calor|is lost as heat', 'viene del Sol|ve del Sol|comes from the Sun'], 'La energía es la que se pierde.|L’energia és la que es perd.|Energy is what is lost.'),
      M('Los descomponedores devuelven al suelo…|Els descomponedors tornen al sòl…|Decomposers return to the soil…', 'sales minerales|sals minerals|minerals', ['luz|llum|light', 'plástico|plàstic|plastic'], 'Que usan las plantas.|Que usen les plantes.|Which plants use.'),
    ]),
  '3E-BG-25': lesson(['Somos ecodependientes: dependemos de la naturaleza para el aire, el agua, los alimentos, los materiales y la energía. Los servicios ecosistémicos (polinización, depuración del agua, regulación del clima, suelo fértil) tienen un valor enorme. Cuidar los ecosistemas es cuidarnos.|Som ecodependents: depenem de la natura per a l’aire, l’aigua, els aliments, els materials i l’energia. Els serveis ecosistèmics (pol·linització, depuració de l’aigua, regulació del clima, sòl fèrtil) tenen un valor enorme. Cuidar els ecosistemes és cuidar-nos.|We are eco-dependent: we rely on nature for air, water, food, materials and energy. Ecosystem services (pollination, water purification, climate regulation, fertile soil) are hugely valuable. Caring for ecosystems means caring for ourselves.'],
    '¿Qué pasaría si desaparecieran las abejas?|Què passaria si desaparegueren les abelles?|What would happen if bees disappeared?', ['Muchas plantas no se polinizarían.|Moltes plantes no es pol·linitzarien.|Many plants would not be pollinated.', 'Habría muchos menos frutos y alimentos.|Hi hauria molts menys fruits i aliments.|There would be far less fruit and food.'], [
      M('Un humedal como L’Albufera presta el servicio de…|Un aiguamoll com l’Albufera presta el servei de…|A wetland like L’Albufera provides…', 'depurar el agua y acoger aves|depurar l’aigua i acollir ocells|water purification and bird habitat', ['producir petróleo|produir petroli|oil production', 'fabricar plástico|fabricar plàstic|plastic production'], 'Filtro natural.|Filtre natural.|A natural filter.'),
      TF('Los bosques ayudan a regular el clima.|Els boscos ajuden a regular el clima.|Forests help regulate the climate.', true, 'Absorben CO₂ y retienen agua.|Absorbixen CO₂ i retenen aigua.|They absorb CO₂ and hold water.'),
      M('La interdependencia significa que…|La interdependència significa que…|Interdependence means…', 'los seres vivos dependemos unos de otros y del medio|els éssers vius depenem uns d’altres i del medi|living things depend on each other and their environment', ['cada especie vive aislada|cada espècie viu aïllada|each species lives alone', 'los humanos no dependemos de nada|els humans no depenem de res|humans depend on nothing'], 'Todo está conectado.|Tot està connectat.|Everything is connected.'),
      M('¿Qué servicio ecosistémico da un suelo fértil?|Quin servei ecosistèmic dona un sòl fèrtil?|What service does fertile soil provide?', 'producción de alimentos|producció d’aliments|food production', ['electricidad|electricitat|electricity', 'internet|internet|the internet'], 'Agricultura.|Agricultura.|Farming.'),
      TF('La economía humana puede funcionar sin la naturaleza.|L’economia humana pot funcionar sense la natura.|The human economy can work without nature.', false, 'Todos los recursos salen de ella.|Tots els recursos n’ixen.|All resources come from it.'),
      M('Una acción que reduce nuestra huella ecológica es…|Una acció que reduïx la nostra petjada ecològica és…|One action that shrinks our ecological footprint is…', 'consumir menos y de proximidad|consumir menys i de proximitat|consuming less and locally', ['viajar más en avión|viatjar més en avió|flying more', 'usar más plástico|usar més plàstic|using more plastic'], 'Menos recursos y transporte.|Menys recursos i transport.|Fewer resources and less transport.'),
    ]),
  '3E-BG-26': lesson(['La salud humana depende de la salud del medio ambiente (enfoque «Una sola salud»): la contaminación del aire causa enfermedades respiratorias; el agua contaminada, infecciones; la pérdida de biodiversidad y el contacto con animales salvajes favorecen nuevas enfermedades (zoonosis); el calor extremo afecta a mayores y niños.|La salut humana depén de la salut del medi ambient (enfocament «Una sola salut»): la contaminació de l’aire causa malalties respiratòries; l’aigua contaminada, infeccions; la pèrdua de biodiversitat i el contacte amb animals salvatges afavorixen noves malalties (zoonosis); la calor extrema afecta majors i xiquets.|Human health depends on environmental health ("One Health"): air pollution causes respiratory disease; polluted water, infections; biodiversity loss and contact with wild animals encourage new diseases (zoonoses); extreme heat affects the elderly and children.'],
    '¿Qué es una zoonosis?|Què és una zoonosi?|What is a zoonosis?', ['Zoo = animal.|Zoo = animal.|Zoo = animal.', 'Una enfermedad que pasa de animales a personas.|Una malaltia que passa d’animals a persones.|A disease passed from animals to people.'], [
      M('La contaminación del aire en ciudades afecta sobre todo a…|La contaminació de l’aire en ciutats afecta sobretot…|City air pollution mainly affects the…', 'los pulmones y el corazón|els pulmons i el cor|lungs and heart', ['los huesos|els ossos|bones', 'el pelo|els cabells|hair'], 'Partículas y gases.|Partícules i gasos.|Particles and gases.'),
      M('El enfoque «Una sola salud» relaciona…|L’enfocament «Una sola salut» relaciona…|The "One Health" approach links…', 'salud humana, animal y ambiental|salut humana, animal i ambiental|human, animal and environmental health', ['solo médicos y hospitales|només metges i hospitals|only doctors and hospitals', 'deporte y música|esport i música|sport and music'], 'Todo está conectado.|Tot està connectat.|All are connected.'),
      TF('Las olas de calor son un riesgo para la salud.|Les onades de calor són un risc per a la salut.|Heatwaves are a health risk.', true, 'Golpes de calor, deshidratación.|Colps de calor, deshidratació.|Heatstroke, dehydration.'),
      M('El mosquito tigre puede transmitir enfermedades como…|El mosquit tigre pot transmetre malalties com…|The tiger mosquito can spread diseases such as…', 'el dengue|el dengue|dengue', ['la caries|la càries|tooth decay', 'la miopía|la miopia|short-sightedness'], 'Se ha extendido con el clima más cálido.|S’ha estés amb el clima més càlid.|It has spread with warmer climate.'),
      M('Beber agua no potable puede causar…|Beure aigua no potable pot causar…|Drinking unsafe water can cause…', 'infecciones intestinales|infeccions intestinals|gut infections', ['más fuerza|més força|more strength', 'mejor vista|millor vista|better eyesight'], 'Cólera, gastroenteritis.|Còlera, gastroenteritis.|Cholera, gastroenteritis.'),
      TF('Proteger los ecosistemas ayuda a prevenir pandemias.|Protegir els ecosistemes ajuda a prevenir pandèmies.|Protecting ecosystems helps prevent pandemics.', true, 'Menos contacto con virus de animales salvajes.|Menys contacte amb virus d’animals salvatges.|Less contact with wildlife viruses.'),
    ]),
  '3E-BG-27': lesson(['La salud no está repartida por igual: depende de la renta, la educación, el acceso al agua potable, la vivienda y los servicios sanitarios. Por eso la esperanza de vida varía mucho entre países y entre barrios. Los sistemas sanitarios públicos y la cooperación reducen estas desigualdades.|La salut no està repartida per igual: depén de la renda, l’educació, l’accés a l’aigua potable, l’habitatge i els serveis sanitaris. Per això l’esperança de vida varia molt entre països i entre barris. Els sistemes sanitaris públics i la cooperació reduïxen estes desigualtats.|Health is not shared equally: it depends on income, education, access to clean water, housing and health services. That is why life expectancy varies widely between countries and even neighbourhoods. Public health systems and cooperation reduce these inequalities.'],
    '¿Por qué la esperanza de vida es menor en algunos países?|Per què l’esperança de vida és menor en alguns països?|Why is life expectancy lower in some countries?', ['Menos acceso a agua potable, vacunas y médicos.|Menys accés a aigua potable, vacunes i metges.|Less access to clean water, vaccines and doctors.', 'También influyen la pobreza y los conflictos.|També influïxen la pobresa i els conflictes.|Poverty and conflict matter too.'], [
      M('¿Qué factor influye más en la salud de una población?|Quin factor influïx més en la salut d’una població?|Which factor most affects a population’s health?', 'el acceso a agua potable y saneamiento|l’accés a aigua potable i sanejament|access to clean water and sanitation', ['el color de las casas|el color de les cases|the colour of houses', 'el idioma|l’idioma|the language'], 'Evita muchas enfermedades.|Evita moltes malalties.|It prevents many diseases.'),
      TF('Un sistema sanitario público ayuda a que todas las personas reciban atención.|Un sistema sanitari públic ajuda que totes les persones reben atenció.|A public health system helps everyone get care.', true, 'Independientemente de sus ingresos.|Independentment dels seus ingressos.|Regardless of income.'),
      M('La desnutrición infantil afecta sobre todo a…|La desnutrició infantil afecta sobretot…|Child malnutrition mainly affects…', 'países con pobreza o conflictos|països amb pobresa o conflictes|countries with poverty or conflict', ['solo a países ricos|només països rics|only rich countries', 'a nadie|ningú|nobody'], 'Según UNICEF.|Segons UNICEF.|According to UNICEF.'),
      M('El nivel educativo influye en la salud porque…|El nivell educatiu influïx en la salut perquè…|Education affects health because…', 'permite tomar decisiones informadas|permet prendre decisions informades|it helps people make informed choices', ['hace crecer más|fa créixer més|it makes you taller', 'no influye|no influïx|it has no effect'], 'Prevención y hábitos.|Prevenció i hàbits.|Prevention and habits.'),
      TF('La esperanza de vida es igual en todos los países del mundo.|L’esperança de vida és igual en tots els països del món.|Life expectancy is the same in every country.', false, 'Hay más de 20 años de diferencia entre algunos.|Hi ha més de 20 anys de diferència entre alguns.|Some differ by over 20 years.'),
      M('La cooperación internacional en salud sirve para…|La cooperació internacional en salut servix per a…|International health cooperation helps to…', 'llevar vacunas y medicamentos donde faltan|portar vacunes i medicaments on falten|bring vaccines and medicines where they are lacking', ['vender más medicinas|vendre més medicines|sell more medicines', 'cerrar hospitales|tancar hospitals|close hospitals'], 'ODS 3: salud y bienestar.|ODS 3: salut i benestar.|SDG 3: good health.'),
    ]),
  '3E-BG-28': lesson(['La corresponsabilidad ambiental significa que todos (personas, empresas, administraciones) compartimos la tarea de cuidar el planeta. Acciones: consumo responsable, movilidad sostenible, ahorro de agua y energía, separar residuos, participar en proyectos locales (limpieza de playas, huertos escolares, voluntariado).|La corresponsabilitat ambiental significa que tots (persones, empreses, administracions) compartim la tasca de cuidar el planeta. Accions: consum responsable, mobilitat sostenible, estalvi d’aigua i energia, separar residus, participar en projectes locals (neteja de platges, horts escolars, voluntariat).|Shared environmental responsibility means that everyone (people, businesses, governments) shares the job of caring for the planet. Actions: responsible consumption, sustainable transport, saving water and energy, sorting waste, and joining local projects (beach clean-ups, school gardens, volunteering).'],
    '¿Qué puede hacer el instituto?|Què pot fer l’institut?|What can a school do?', ['Reducir papel y plásticos, separar residuos.|Reduir paper i plàstics, separar residus.|Cut paper and plastic, sort waste.', 'Huerto escolar, ahorro energético, rutas seguras en bici.|Hort escolar, estalvi energètic, rutes segures en bici.|A school garden, energy saving, safe cycle routes.'], [
      M('El consumo responsable consiste en…|El consum responsable consistix en…|Responsible consumption means…', 'comprar lo necesario y con menor impacto|comprar el necessari i amb menys impacte|buying what you need, with less impact', ['comprar todo lo que se anuncia|comprar tot el que s’anuncia|buying everything advertised', 'no comprar nunca nada|no comprar mai res|never buying anything'], 'Pensar antes de comprar.|Pensar abans de comprar.|Think before you buy.'),
      TF('Las empresas también tienen responsabilidad ambiental.|Les empreses també tenen responsabilitat ambiental.|Businesses also have environmental responsibility.', true, 'Producción limpia, menos residuos.|Producció neta, menys residus.|Clean production, less waste.'),
      M('Un ejemplo de movilidad sostenible es…|Un exemple de mobilitat sostenible és…|An example of sustainable transport is…', 'ir en bici o en transporte público|anar en bici o en transport públic|cycling or public transport', ['ir solo en coche a todas partes|anar sol en cotxe a tot arreu|driving alone everywhere', 'viajes cortos en avión|viatges curts en avió|short flights'], 'Menos emisiones por persona.|Menys emissions per persona.|Fewer emissions per person.'),
      M('Participar en una limpieza de playa es…|Participar en una neteja de platja és…|Joining a beach clean-up is…', 'una acción de voluntariado ambiental|una acció de voluntariat ambiental|environmental volunteering', ['inútil|inútil|pointless', 'obligatorio por ley|obligatori per llei|required by law'], 'Y sensibiliza.|I sensibilitza.|And raises awareness.'),
      TF('Las administraciones pueden promover el cuidado ambiental con leyes y ayudas.|Les administracions poden promoure la cura ambiental amb lleis i ajudes.|Governments can promote environmental care with laws and grants.', true, 'Por ejemplo, zonas de bajas emisiones.|Per exemple, zones de baixes emissions.|For example, low-emission zones.'),
      M('Un huerto escolar ayuda a…|Un hort escolar ajuda a…|A school garden helps…', 'aprender sobre alimentos, suelo y biodiversidad|aprendre sobre aliments, sòl i biodiversitat|learn about food, soil and biodiversity', ['contaminar menos el aire de la ciudad entera|contaminar menys l’aire de tota la ciutat|clean the whole city’s air', 'nada|res|nothing'], 'Aprender haciendo.|Aprendre fent.|Learning by doing.'),
    ]),
};
export default P;
